export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  // ADR-0056: карточка не редактируется — cardMessageId больше не нужен.
  // Шаг сессии живёт в JSON draft (reg-profile читает draft.step): ob_lang
  // (язык ещё не выбран, W114) или ob_consent.
  const step = str(inputs.sessionStep) === 'ob_lang' ? 'ob_lang' : 'ob_consent';
  const draft = {
    eventId: str(inputs.eventId),
    utm: str(inputs.utm),
    step: step
  };
  return { draft: JSON.stringify(draft) };
};

export const code = async (inputs) => {
  // W50 / PAR-8 / ADR-0043: вход в онбординг — карточка события + «зачем
  // данные» + текст согласия ОДНОЙ карточкой (ADR-0043: отдельного экрана
  // согласия больше нет; нажатие «Согласен» — это согласие). «Подробнее»
  // остаётся второй кнопкой (полный текст согласия), оттуда же доступен
  // отказ (`ob:decline`). Согласие переспрашиваем даже при consent_pdn=true:
  // старый объём согласия покрывал регистрацию, а не поля профиля
  // (должность/компания/город).
  // W114: если язык ещё не выбран (users.lang пуст), первой карточкой
  // онбординга идёт вопрос о языке: те же факты события + `lang.ask` и три
  // кнопки ob:lang:*. Шаг сессии — ob_lang, дальше reg-profile отдаёт
  // карточку согласия.
  // W125 (OWN-17): в фактах карточки — язык контента события.
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] || key);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const esc = (v) => String(v === undefined || v === null ? '' : v)
    .replace(/\\/g, '\\\\')
    .replace(/([_*\[\]()~`>#+\-=|{}.!])/g, '\\$1');
  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const s = /[Zz]$/.test(iso) || /[+-][0-9]{2}:?[0-9]{2}$/.test(iso) ? iso : iso + 'Z';
    const d = new Date(s);
    return isNaN(d.getTime()) ? '' : dateFmt.format(d);
  };
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const lat = Number(inputs.lat);
  const lon = Number(inputs.lon);
  // W72 (#124): пустые координаты — это '' , а не 0 (Number('') === 0 давал
  // ссылку на точку 0,0 в Атлантике), и координаты должны быть в диапазоне.
  // Та же проверка, что в reg-profile/reg-consent-mkt.
  const hasGeo = str(inputs.lat) !== '' && str(inputs.lon) !== '' && isFinite(lat) && isFinite(lon) && lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180 && !(lat === 0 && lon === 0);
  const mapsUrl = hasGeo ? ('https://yandex.uz/maps/?ll=' + lon + '%2C' + lat + '&z=17&pt=' + lon + '%2C' + lat) : '';
  const lines = [];
  if (str(inputs.title)) lines.push('*' + esc(str(inputs.title)) + '*');
  if (str(inputs.description)) lines.push(esc(str(inputs.description)));
  const facts = [];
  if (str(inputs.startsAt)) facts.push('📅 ' + esc(fmt(str(inputs.startsAt))) + (str(inputs.endsAt) ? ' — ' + esc(fmt(str(inputs.endsAt))) : ''));
  if (str(inputs.address)) facts.push('📍 ' + esc(str(inputs.address)));
  if (str(inputs.lang)) facts.push(esc(t('event.card.lang', { lang: str(inputs.lang).toUpperCase() })));
  if (mapsUrl) facts.push('🗺 [Открыть на карте](' + mapsUrl + ')');
  if (str(inputs.regDeadlineAt)) facts.push('⏳ ' + esc(t('event.card.deadline_short', { when: fmt(str(inputs.regDeadlineAt)) })));
  if (facts.length) lines.push(facts.join('\n'));
  const needsLang = inputs.needsLang === true || String(inputs.needsLang) === 'true';
  let replyMarkup;
  let sessionStep;
  if (needsLang) {
    lines.push(esc(t('lang.ask')));
    replyMarkup = {
      inline_keyboard: [[
        { text: t('lang.btn.ru'), callback_data: 'ob:lang:ru' },
        { text: t('lang.btn.uz'), callback_data: 'ob:lang:uz' },
        { text: t('lang.btn.en'), callback_data: 'ob:lang:en' }
      ]]
    };
    sessionStep = 'ob_lang';
  } else {
    lines.push(esc(t('onb.why')));
    lines.push(esc(t('onb.consent')));
    replyMarkup = {
      inline_keyboard: [[
        { text: t('onb.btn.agree'), callback_data: 'ob:agree' },
        { text: t('onb.btn.details'), callback_data: 'ob:details' }
      ]]
    };
    sessionStep = 'ob_consent';
  }
  return { text: lines.join('\n\n'), replyMarkup: replyMarkup, mapsUrl: mapsUrl, now: new Date().toISOString(), sessionStep: sessionStep };
};

export const code = async (inputs) => {
